$files = Get-ChildItem -Recurse -File src/views/supervision -Filter index.vue
foreach($f in $files){
  $raw = Get-Content $f.FullName -Raw
  # find each occurrence of prop: 'bizState' and look back for the opening brace to get the type on same object
  $ms = [regex]::Matches($raw, "prop:\s*'bizState'")
  foreach($m in $ms){
    $start = [Math]::Max(0, $m.Index-260)
    $seg = $raw.Substring($start, $m.Index-$start+40)
    # find last '{' before prop
    $lastBrace = $seg.LastIndexOf('{')
    $objStart = $seg.Substring($lastBrace)
    $hasDict = $objStart -match "dictUrl|dict-url"
    $typeMatch = [regex]::Match($objStart, "type:\s*'([^']+)'")
    $type = if($typeMatch.Success){$typeMatch.Groups[1].Value}else{'(none)'}
    if(-not $hasDict -or $type -ne 'dict'){
      Write-Host "$($f.FullName.Replace('D:\repository\苏州市房地产监测V3\zhi2-web-admin\','')) | type=$type | dictUrl=$hasDict"
    }
  }
}

