import { chromium } from '@playwright/test'
import {
  loginWithRealAccount,
  collectAppRoutes,
  gotoHashPath,
  waitForPageLoading,
  waitForRoutesReady,
  ensureDynamicRoutesRegistered
} from '../fixtures/auth-helpers.js'

const BASE = process.env.E2E_BASE_URL || 'http://58.210.252.230:9002'

async function dumpBizState(page, filePath) {
  const routes = await collectAppRoutes(page)
  const listRoute = routes.find(
    (r) => r.filePath === filePath && !String(r.path).includes(':tableid')
  )
  if (!listRoute) {
    console.log(`[MISS] ${filePath} 未注册`)
    return
  }
  await gotoHashPath(page, listRoute.path)
  await waitForPageLoading(page)
  await page.waitForTimeout(2500)
  // 表格列头 + 行内 bizState 列文本
  const headerTexts = await page.$$eval('.el-table__header-wrapper th .cell', (els) =>
    els.map((e) => e.textContent.trim())
  )
  const bizColIndex = headerTexts.findIndex((t) => t === '业务状态')
  let cellTexts = []
  if (bizColIndex >= 0) {
    cellTexts = await page.$$eval('.el-table__body-wrapper tbody tr', (rows, idx) => {
      return rows.slice(0, 8).map((tr) => {
        const tds = tr.querySelectorAll('td .cell')
        return tds[idx] ? tds[idx].textContent.trim() : ''
      })
    }, bizColIndex)
  }
  console.log(`\n[PAGE] ${filePath}  route=${listRoute.path}`)
  console.log(`  表头: ${headerTexts.join(' | ')}`)
  console.log(`  业务状态列索引=${bizColIndex}  值样本=${JSON.stringify(cellTexts)}`)
}

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const context = await browser.newContext({ ignoreHTTPSErrors: true })
  const page = await context.newPage()
  page.on('console', (m) => {
    const t = m.text()
    if (/dict|biz_state|字典/i.test(t)) console.log('  [console]', t)
  })
  try {
    console.log('BASE=', BASE)
    await page.goto(BASE + '/#/', { waitUntil: 'domcontentloaded' })
    await loginWithRealAccount(page, {
      loginType: 'account',
      username: 'zsbase',
      password: 'ZS001Aa!'
    })
    await waitForRoutesReady(page)
    await ensureDynamicRoutesRegistered(page)
    console.log('LOGIN OK. url=', page.url())

    // 拦截字典接口，观察 biz_state 返回
    const bizResp = []
    page.on('response', async (r) => {
      if (r.url().includes('/system/dictData/listByType')) {
        try {
          const req = r.request().postData() || ''
          if (req.includes('biz_state')) {
            const j = await r.json()
            bizResp.push(Array.isArray(j?.data) ? j.data.length : ('非数组:' + (j?.code)))
          }
        } catch (e) { bizResp.push('ERR:' + e.message) }
      }
    })

    for (const fp of [
      'supervision/agreement/account/index',
      'supervision/deposit/notice/index',
      'supervision/progress/node/index',
      'supervision/projectDelivery/index'
    ]) {
      await dumpBizState(page, fp)
    }
    console.log('\n[biz_state 字典接口返回条数样本]:', JSON.stringify(bizResp))
  } catch (e) {
    console.error('PROBE ERROR:', e.message)
  } finally {
    await browser.close()
  }
})()

