/** bizState 列优先使用列级 options / dict-url，避免误用全局 biz_state 字典 */
bizStateColumnOptions() {
  if (Array.isArray(this.$attrs.options) && this.$attrs.options.length) {
    return this.$attrs.options
  }
  if (Array.isArray(this.options) && this.options.length) {
    return this.options
  }
  // 兜底：全局 biz_state 字典（路由守卫预加载，见 utils/bizState.js）。
  // 不使用 this.bizStateOptions：它来自全局 mixin 的 data 快照，非响应式，
  // 组件早于字典就绪创建时会永久停留在空数组，导致业务状态显示为数字码值。
  const globalOpts = getGlobalBizStateOptions()
  if (Array.isArray(globalOpts) && globalOpts.length) {
    return globalOpts
  }
  return this.bizStateOptions || []
},

